-- Hosted-safe fixtures: everything, including Auth users, rolls back.
begin;
create temp table crud_ids(key text primary key,id uuid);
insert into crud_ids values('owner','b41f0000-0000-4000-8000-000000000001'),('other','b41f0000-0000-4000-8000-000000000002'),('customer','b41f0000-0000-4000-8000-000000000003');
insert into auth.users(id,email) select id,key||'-crud-fixture@example.invalid' from crud_ids;
create function pg_temp.cid(k text) returns uuid language sql stable as $$select id from pg_temp.crud_ids where key=k$$;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.denied(statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Unauthorized operation succeeded';end;$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on crud_ids to authenticated;
grant execute on function pg_temp.cid(text),pg_temp.ok(boolean,text),pg_temp.denied(text,text) to authenticated,anon;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'))::text,true);
set local role authenticated;
insert into crud_ids values('salon',gen_random_uuid()),('unused',gen_random_uuid()),('barber',gen_random_uuid()),('service',gen_random_uuid()),('tempbarber',gen_random_uuid());
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.cid('salon'),'name','CRUD fixture salon','address','Akurana','service_name','Haircut','duration_minutes',45,'price_min_minor',100000,'price_max_minor',140000,'opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)));
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.cid('unused'),'name','Unused fixture salon','address','Akurana','service_name','Haircut','duration_minutes',45,'price_min_minor',100000,'price_max_minor',140000,'opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)));
insert into crud_ids select 'haircut',(s->'services'->0->>'id')::uuid from jsonb_array_elements(public.manager_state()->'salons')s where s->>'id'=pg_temp.cid('salon')::text;
select public.manager_command('create_service',jsonb_build_object('id',pg_temp.cid('service'),'salon_id',pg_temp.cid('salon'),'name','Beard','duration_minutes',15,'price_min_minor',50000,'price_max_minor',70000));
select public.manager_command('create_service',jsonb_build_object('id',pg_temp.cid('service'),'salon_id',pg_temp.cid('salon'),'name','Beard','duration_minutes',15,'price_min_minor',50000,'price_max_minor',70000));
select pg_temp.ok((select count(*)=1 from public.services where id=pg_temp.cid('service')),'Create retry never duplicates a service');
select pg_temp.denied($q$select public.manager_command('create_service',jsonb_build_object('id',gen_random_uuid(),'salon_id',pg_temp.cid('salon'),'name',' beard ','duration_minutes',15,'price_min_minor',50000,'price_max_minor',70000))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('service',jsonb_build_object('id',pg_temp.cid('service'),'salon_id',pg_temp.cid('salon'),'name','Beard','duration_minutes',0,'price_min_minor',1,'price_max_minor',2))$q$,'P0001');
select public.manager_command('service',jsonb_build_object('id',pg_temp.cid('service'),'salon_id',pg_temp.cid('salon'),'name','Beard trim','duration_minutes',20,'price_min_minor',60000,'price_max_minor',80000));
select pg_temp.ok((select name='Beard trim' and duration_minutes=20 and price_min_minor=60000 from public.services where id=pg_temp.cid('service')),'Service update persists');
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon'),'display_name','CRUD chair','specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.cid('haircut'))));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.cid('tempbarber'),'salon_id',pg_temp.cid('unused'),'display_name','Unused chair','specialities','[]'::jsonb,'service_ids',(select jsonb_build_array(s->'services'->0->'id') from jsonb_array_elements(public.manager_state()->'salons')s where s->>'id'=pg_temp.cid('unused')::text)::jsonb));
-- Unused records can actually be deleted; no cascade through service history.
select public.manager_command('delete_service',jsonb_build_object('id',pg_temp.cid('service'),'salon_id',pg_temp.cid('salon')));
select pg_temp.ok(not exists(select 1 from public.services where id=pg_temp.cid('service')),'Unused service permanently deleted');
select public.manager_command('delete_barber',jsonb_build_object('id',pg_temp.cid('tempbarber'),'salon_id',pg_temp.cid('unused')));
select pg_temp.ok(not exists(select 1 from public.barbers where id=pg_temp.cid('tempbarber')),'Unused barber permanently deleted');
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.cid('tempbarber'),'salon_id',pg_temp.cid('unused'),'display_name','Unused chair retry','specialities','[]'::jsonb,'service_ids',(select jsonb_build_array(s->'services'->0->'id') from jsonb_array_elements(public.manager_state()->'salons')s where s->>'id'=pg_temp.cid('unused')::text)));
select public.manager_command('delete_salon',jsonb_build_object('salon_id',pg_temp.cid('unused')));
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.manager_state()->'salons')s where s->>'id'=pg_temp.cid('unused')::text),'Unused salon removed from manager account');
reset role;
select pg_temp.ok(exists(select 1 from bookmyturn_private.audit_events where entity_id=pg_temp.cid('unused')::text and operation='DELETE' and salon_id is null),'Deleted salon audit survives');
select pg_temp.ok(not exists(select 1 from public.services where salon_id=pg_temp.cid('unused')),'Unused salon configuration removed');
set local role authenticated;
-- A different manager cannot mutate either the parent or a supplied child ID.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('other'))::text,true);
select pg_temp.denied($q$select public.manager_command('delete_salon',jsonb_build_object('salon_id',pg_temp.cid('salon')))$q$,'42501');
select pg_temp.denied($q$select public.manager_command('archive_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')))$q$,'42501');
select pg_temp.denied($q$select public.manager_command('restore_service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon')))$q$,'42501');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'))::text,true);
-- Weekly schedule updates propagate to existing chairs, with independent day hours.
select public.manager_command('salon',jsonb_build_object('salon_id',pg_temp.cid('salon'),'name','CRUD fixture updated','address','New address','photo_url','','is_open',true,'hours',(select jsonb_agg(jsonb_build_object('weekday',d,'opens_at','00:00','closes_at','23:58')) from generate_series(0,6)d)));
select pg_temp.denied($q$select public.manager_command('salon',jsonb_build_object('salon_id',pg_temp.cid('salon'),'name','Bad schedule','address','Akurana','hours',jsonb_build_array(jsonb_build_object('weekday',1,'opens_at','20:00','closes_at','09:00'))))$q$,'P0001');
reset role;
select pg_temp.ok((select count(*)=7 from public.barber_hours where barber_id=pg_temp.cid('barber') and ends_at='23:58'::time),'Changed salon hours propagate to all team days');
set local role authenticated;
-- A real future appointment protects all three levels and its allocated duration.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('customer'))::text,true);
insert into crud_ids select 'appointment',(public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.cid('salon'),'service_id',pg_temp.cid('haircut'),'barber_id',pg_temp.cid('barber'),'starts_at',((now() at time zone 'Asia/Colombo')::date+1+'14:00'::time) at time zone 'Asia/Colombo','request_key',gen_random_uuid()))->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'))::text,true);
select pg_temp.denied($q$select public.manager_command('archive_salon',jsonb_build_object('salon_id',pg_temp.cid('salon')))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('delete_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('archive_service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon')))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon'),'name','Haircut','duration_minutes',60,'price_min_minor',100000,'price_max_minor',140000))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('salon',jsonb_build_object('salon_id',pg_temp.cid('salon'),'name','Bad hours','address','Akurana','hours',(select jsonb_agg(jsonb_build_object('weekday',d,'opens_at','09:00','closes_at','13:00')) from generate_series(0,6)d)))$q$,'P0001');
select pg_temp.denied($q$select public.barber_command(pg_temp.cid('barber'),'service',jsonb_build_object('id',pg_temp.cid('haircut'),'name','Haircut','duration_minutes',60,'price_min_minor',100000,'price_max_minor',140000))$q$,'P0001');
select public.barber_command(pg_temp.cid('barber'),'decline',jsonb_build_object('id',pg_temp.cid('appointment')));
-- Create immutable completed service/financial history on the managed chair.
insert into crud_ids select 'queue',(public.barber_command(pg_temp.cid('barber'),'walk_in',jsonb_build_object('request_key',gen_random_uuid(),'service_id',pg_temp.cid('haircut'),'customer_name','CRUD walk-in'))->>'id')::uuid;
select pg_temp.denied($q$select public.manager_command('archive_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')))$q$,'P0001');
insert into crud_ids select 'session',(public.barber_command(pg_temp.cid('barber'),'start',jsonb_build_object('id',pg_temp.cid('queue'),'agreed_price_minor',120000,'price_agreed',true))->>'id')::uuid;
select public.barber_command(pg_temp.cid('barber'),'finish',jsonb_build_object('id',pg_temp.cid('session'),'final_amount_minor',120000,'final_agreed',true));
select pg_temp.denied($q$select public.manager_command('delete_service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon')))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('delete_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('delete_salon',jsonb_build_object('salon_id',pg_temp.cid('salon')))$q$,'P0001');
reset role;
select pg_temp.ok(exists(select 1 from public.barber_services where barber_id=pg_temp.cid('barber')),'Failed delete rolls all configuration changes back');
select pg_temp.ok(exists(select 1 from public.service_sessions where id=pg_temp.cid('session') and final_amount_minor=120000),'Financial service snapshot survives');
set local role authenticated;
select public.manager_command('archive_service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon')));
select public.manager_command('archive_service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon')));
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.customer_catalog()->'services')s where s->>'id'=pg_temp.cid('haircut')::text),'Archived service hidden from customer catalogue');
select public.manager_command('archive_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')));
select pg_temp.denied($q$select public.manager_command('restore_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')))$q$,'P0001');
select public.manager_command('restore_service',jsonb_build_object('id',pg_temp.cid('haircut'),'salon_id',pg_temp.cid('salon')));
select public.manager_command('restore_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon')));
select pg_temp.ok(jsonb_array_length(public.barber_context())=1,'Restored barber operational again');
select public.manager_command('archive_salon',jsonb_build_object('salon_id',pg_temp.cid('salon')));
select pg_temp.ok(jsonb_array_length(public.barber_context())=0,'Archived salon cannot operate chairs');
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.customer_catalog()->'salons')s where s->>'id'=pg_temp.cid('salon')::text),'Archived salon hidden from customer discovery');
select pg_temp.ok(not exists(select 1 from public.barbers where id=pg_temp.cid('barber')),'Direct API cannot list archived salon barbers');
select pg_temp.denied($q$select public.barber_state(pg_temp.cid('barber'))$q$,'42501');
select pg_temp.denied($q$select public.manager_command('create_service',jsonb_build_object('id',gen_random_uuid(),'salon_id',pg_temp.cid('salon'),'name','Hidden service','duration_minutes',30,'price_min_minor',1,'price_max_minor',2))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('customer'))::text,true);
select pg_temp.ok(exists(select 1 from public.appointments where id=pg_temp.cid('appointment')),'Customer keeps historical appointment access');
select pg_temp.denied($q$select public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.cid('salon'),'service_id',pg_temp.cid('haircut'),'barber_id',pg_temp.cid('barber'),'starts_at',((now() at time zone 'Asia/Colombo')::date+2+'14:00'::time) at time zone 'Asia/Colombo','request_key',gen_random_uuid()))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'))::text,true);
select public.manager_command('restore_salon',jsonb_build_object('salon_id',pg_temp.cid('salon')));
select pg_temp.ok((select not is_open from public.salons where id=pg_temp.cid('salon')),'Restored salon remains closed for manager review');
select pg_temp.ok(jsonb_array_length(public.barber_context())=1,'Salon restore returns active chairs');
reset role;
select 'PASS: catalogue CRUD, retries, schedule validation, active-visit guards, archive/restore, history and tenant isolation' result;
rollback;
